import{_ as d,r as o,o as r,c as n,e as c,a as s,s as l}from"./chunks/framework.CXcwiNg-.js";const D=JSON.parse('{"title":"Основы работы с базами данных - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Настройка","slug":"настроика","link":"#настроика","children":[{"level":3,"title":"Чтение / Запись","slug":"чтение-запись","link":"#чтение-запись","children":[]}]},{"level":2,"title":"Выполнение сырых SQL-запросов","slug":"выполнение-сырых-sql-запросов","link":"#выполнение-сырых-sql-запросов","children":[{"level":4,"title":"Выполнение запроса SELECT","slug":"выполнение-запроса-select","link":"#выполнение-запроса-select","children":[]},{"level":4,"title":"Использование привязки имён","slug":"использование-привязки-имен","link":"#использование-привязки-имен","children":[]},{"level":4,"title":"Выполнение запроса INSERT","slug":"выполнение-запроса-insert","link":"#выполнение-запроса-insert","children":[]},{"level":4,"title":"Выполнение запроса UPDATE","slug":"выполнение-запроса-update","link":"#выполнение-запроса-update","children":[]},{"level":4,"title":"Выполнение запроса DELETE","slug":"выполнение-запроса-delete","link":"#выполнение-запроса-delete","children":[]},{"level":4,"title":"Выполнение запроса общего типа","slug":"выполнение-запроса-общего-типа","link":"#выполнение-запроса-общего-типа","children":[]}]},{"level":2,"title":"Использование нескольких соединений с БД","slug":"использование-нескольких-соединении-с-бд","link":"#использование-нескольких-соединении-с-бд","children":[]},{"level":2,"title":"Транзакции","slug":"транзакции","link":"#транзакции","children":[{"level":4,"title":"Ручное использование транзакций","slug":"ручное-использование-транзакции","link":"#ручное-использование-транзакции","children":[]}]},{"level":2,"title":"Прослушивание событий запросов","slug":"прослушивание-событии-запросов","link":"#прослушивание-событии-запросов","children":[{"level":3,"title":"Журнал запросов","slug":"журнал-запросов","link":"#журнал-запросов","children":[]}]}],"relativePath":"1.x/ru/database/basics.md","filePath":"1.x/ru/database/basics.md"}'),i={name:"1.x/ru/database/basics.md"};function p(h,e,u,g,b,m){const a=o("pre-heading"),t=o("post-heading");return r(),n("div",null,[c(a),e[0]||(e[0]=s("h1",null,"Основы работы с базами данных",-1)),c(t),e[1]||(e[1]=l(`<p><a name="introduction" class="anchor"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>В OctoberCMS можно настроить соединение с БД и выполнять запросы чрезвычайно просто для различных «движков» БД, будь то сырой SQL, <a href="./../database/query.html">гибкий строитель запросов</a> или <a href="./../database/model.html">Active Record</a>. Работа с таблицами и начальными данными описана в разделе <a href="./../database/structure.html">Структура базы данных</a>.</p><p><a name="configuration" class="anchor"></a></p><h2 id="настроика"><a href="#настроика" class="header-anchor">#</a> Настройка</h2><p>Настройки БД вашего приложения хранятся в файле <code>config/database.php</code>. Здесь вы можете указать все используемые вами соединения, а также задать соединение по умолчанию. Примеры настройки всех возможных видов подключений находятся в этом же файле.</p><p><a name="read-write-connections" class="anchor"></a></p><h3 id="чтение-запись"><a href="#чтение-запись" class="header-anchor">#</a> Чтение / Запись</h3><p>Иногда вам может понадобиться использовать разные подключения к базе данных: одно для запросов SELECT, а другое для запросов INSERT, UPDATE и DELETE. Сделать это очень просто! При этом всегда будет использоваться соответствующее соединение вне зависимости от типа запроса.</p><p>Чтобы увидеть, как должны быть настроены соединения чтения/записи, давайте рассмотрим этот пример:</p><pre><code>&#39;mysql&#39; =&gt; [
    &#39;read&#39; =&gt; [
        &#39;host&#39; =&gt; &#39;192.168.1.1&#39;,
    ],
    &#39;write&#39; =&gt; [
        &#39;host&#39; =&gt; &#39;196.168.1.2&#39;
    ],
    &#39;driver&#39;    =&gt; &#39;mysql&#39;,
    &#39;database&#39;  =&gt; &#39;database&#39;,
    &#39;username&#39;  =&gt; &#39;root&#39;,
    &#39;password&#39;  =&gt; &#39;&#39;,
    &#39;charset&#39;   =&gt; &#39;utf8&#39;,
    &#39;collation&#39; =&gt; &#39;utf8_unicode_ci&#39;,
    &#39;prefix&#39;    =&gt; &#39;&#39;,
],
</code></pre><p>Обратите внимание на то, что в массив с настройками были добавлены два элемента:  <code>read</code> и <code>write</code> . Оба элемента представляют собой массив с одним элементом &#39;host&#39;. Остальные параметры БД для подключений чтения/записи будут заимствованы из основного массива <code>mysql</code>.</p><p>Поэтому размещать элементы в массивах для этих подключений стоит, только если вы хотите переопределить их значения из основного массива. Таким образом, в этом случае, <code>192.168.1.1</code> будет использоваться как подключение «чтения», а <code>192.168.1.2</code> — как подключение «записи». Учётные данные для БД, префикс, набор символов, и все другие параметры основного массива <code>mysql</code> будут использованы для обоих подключений.</p><p><a name="running-queries" class="anchor"></a></p><h2 id="выполнение-сырых-sql-запросов"><a href="#выполнение-сырых-sql-запросов" class="header-anchor">#</a> Выполнение сырых SQL-запросов</h2><p>Когда вы настроили соединение с базой данных, вы можете выполнять запросы, используя фасад <code>Db</code>. Этот фасад имеет методы для каждого типа запроса: <code>select</code>, <code>update</code>, <code>insert</code>, <code>delete</code> и <code>statement</code>.</p><h4 id="выполнение-запроса-select"><a href="#выполнение-запроса-select" class="header-anchor">#</a> Выполнение запроса SELECT</h4><p>Вы можете использовать метод <code>select</code> фасада <code>Db</code>, чтобы выполнить базовый запрос:</p><pre><code>$users = Db::select(&#39;select * from users where active = ?&#39;, [1]);
</code></pre><p>Первый аргумент метода <code>select</code> — сырой SQL-запрос, второй — любые связки параметров для прикрепления к запросу. Обычно это значения ограничений условия where. Привязка параметров обеспечивает защиту от SQL-инъекций.</p><p>Метод <code>select</code> всегда возвращает массив результатов. Каждый результат в массиве — объект PHP <code>stdClass</code>, что позволяет вам обращаться к значениям результатов:</p><pre><code>foreach ($users as $user) {
    echo $user-&gt;name;
}
</code></pre><h4 id="использование-привязки-имен"><a href="#использование-привязки-имен" class="header-anchor">#</a> Использование привязки имён</h4><p>Вместо использования знака вопроса <code>?</code> для обозначения привязки параметров, Вы можете выполнить запрос, используя привязку по имени:</p><pre><code>$results = Db::select(&#39;select * from users where id = :id&#39;, [&#39;id&#39; =&gt; 1]);
</code></pre><h4 id="выполнение-запроса-insert"><a href="#выполнение-запроса-insert" class="header-anchor">#</a> Выполнение запроса INSERT</h4><p>Чтобы выполнить запрос <code>insert</code>, можно использовать метод <code>insert</code> фасада DB. Как и <code>select</code>, данный метод принимает сырой SQL-запрос первым аргументом, а вторым — привязки:</p><pre><code>Db::insert(&#39;insert into users (id, name) values (?, ?)&#39;, [1, &#39;Joe&#39;]);
</code></pre><h4 id="выполнение-запроса-update"><a href="#выполнение-запроса-update" class="header-anchor">#</a> Выполнение запроса UPDATE</h4><p>Для обновления существующих записей в БД используется метод <code>update</code>, который возвращает количество изменённых записей:</p><pre><code>$affected = Db::update(&#39;update users set votes = 100 where name = ?&#39;, [&#39;John&#39;]);
</code></pre><h4 id="выполнение-запроса-delete"><a href="#выполнение-запроса-delete" class="header-anchor">#</a> Выполнение запроса DELETE</h4><p>Для удаления записей из БД используется метод <code>delete</code>, который возвращает количество удалённых записей:</p><pre><code>$deleted = Db::delete(&#39;delete from users&#39;);
</code></pre><h4 id="выполнение-запроса-общего-типа"><a href="#выполнение-запроса-общего-типа" class="header-anchor">#</a> Выполнение запроса общего типа</h4><p>Иногда запрос к БД не должен возвращать каких-либо значений. Для операций такого типа можно использовать метод <code>statement</code> фасада <code>Db</code>:</p><pre><code>Db::statement(&#39;drop table users&#39;);
</code></pre><p><a name="accessing-connections" class="anchor"></a></p><h2 id="использование-нескольких-соединении-с-бд"><a href="#использование-нескольких-соединении-с-бд" class="header-anchor">#</a> Использование нескольких соединений с БД</h2><p>При использовании нескольких соединений с БД вы можете получить доступ к каждому из них через метод <code>connection</code> фасада <code>Db</code>. Передаваемое в этот метод имя <code>name</code> должно соответствовать одному из перечисленных в файле <code>config/database.php</code> соединений:</p><pre><code>$users = Db::connection(&#39;foo&#39;)-&gt;select(...);
</code></pre><p>Вы также можете получить низкоуровневый объект PDO для этого подключения методом <code>getPdo</code>:</p><pre><code>$pdo = Db::connection()-&gt;getPdo();
</code></pre><p><a name="database-transactions" class="anchor"></a></p><h2 id="транзакции"><a href="#транзакции" class="header-anchor">#</a> Транзакции</h2><p>Для выполнения набора запросов внутри одной транзакции вы можете использовать метод <code>transaction</code> фасада <code>Db</code>. Если в замыкании транзакции произойдёт исключение, она автоматически откатится. А если замыкание выполнится успешно, транзакция автоматически применится к БД. Вам не стоит переживать об этом при использовании метода <code>transaction</code>:</p><pre><code>Db::transaction(function () {
    Db::table(&#39;users&#39;)-&gt;update([&#39;votes&#39; =&gt; 1]);

    Db::table(&#39;posts&#39;)-&gt;delete();
});
</code></pre><h4 id="ручное-использование-транзакции"><a href="#ручное-использование-транзакции" class="header-anchor">#</a> Ручное использование транзакций</h4><p>Если вы хотите запустить транзакцию вручную и иметь полный контроль над её откатом и применением, используйте метод <code>beginTransaction</code> фасада <code>Db</code>:</p><pre><code>Db::beginTransaction();
</code></pre><p>Вы можете откатить транзакцию методом <code>rollback</code>:</p><pre><code>Db::rollBack();
</code></pre><p>Наконец, вы можете применить транзакцию методом <code>commit</code>:</p><pre><code>Db::commit();
</code></pre><blockquote><p><strong>Примечание:</strong> Методы фасада DB для транзакций также контролируют транзакции <a href="./../database/query.html">построителя запросов</a> и <a href="./../database/model.html">запросов модели</a>.</p></blockquote><p><a name="database-events" class="anchor"></a></p><h2 id="прослушивание-событии-запросов"><a href="#прослушивание-событии-запросов" class="header-anchor">#</a> Прослушивание событий запросов</h2><p>If you would like to receive each SQL query executed by your application, you may use the <code>listen</code> method. This method is useful for logging queries or debugging.</p><pre><code>Db::listen(function($sql, $bindings, $time) {
    //
});
</code></pre><p>Just like <a href="./../services/events.html#event-registration">event registration</a>, you may register your query listener in the <code>boot()</code> method of a <a href="./../plugin/registration.html#registration-methods">Plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place this logic.</p><p><a name="query-logging" class="anchor"></a></p><h3 id="журнал-запросов"><a href="#журнал-запросов" class="header-anchor">#</a> Журнал запросов</h3><p>При включенном логировании OctoberCMS записывает все SQL-запросы, выполненные в рамках текущего запроса страницы. Для подключения журнала вы можете использовать метод <code>enableQueryLog</code>:</p><pre><code>Db::connection()-&gt;enableQueryLog();
</code></pre><p>Чтобы получить массив выполненных запросов, вы можете использовать метод <code>getQueryLog</code>:</p><pre><code>$queries = Db::getQueryLog();
</code></pre><p>Однако, в некоторых случаях — например, при вставке большого набора записей — это может быть слишком ресурсозатратно. Чтобы отключить логирование, используйте метод <code>disableQueryLog</code>:</p><pre><code>Db::connection()-&gt;disableQueryLog();
</code></pre><blockquote><p><strong>Примечание</strong>: Для быстрой отладки приложения лучше использовать метод <code>trace_sql()</code>.</p></blockquote>`,69))])}const v=d(i,[["render",p]]);export{D as __pageData,v as default};
